class ConfigError(Exception):
    def __init__(self, key: str, expected: str, actual: str | None = None):
        msg = f"{key}: expected {expected}, got {actual or 'nothing'}"
        super().__init__(msg)


def coerce(value: str, target_type: type) -> object:
    if target_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(value, "int")
    if target_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(value, "float")
    if target_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError(value, "bool")
    # str: any non-empty string is valid
    if value:
        return value
    raise ConfigError(value, "str")


